waves.point_eqs_eel:
w = min(1, 8 * min(sample, 1 - sample));
x = 0.5 + (sample - 0.5) / aspectx;
y = 0.5 - (0.42 - value1 * 0.35 * w) / aspecty;

frame_eqs_eel:
kick = max(bass - bass_att, 0);
pulse = max(pulse * 0.86, min(kick * 0.9, 1));
q3 = pulse;
pop = max(pop * 0.78, min(max(bass - 1.2, 0) * 0.55, 1.4));
q5 = pop;
dd = 0.005 + 0.012 * min(bass_att, 2.5) + 0.03 * min(kick, 1.5) + 0.02 * pop;
depth = depth + dd;
twist = twist + 0.0015 + 0.003 * (mid_att - 1);
cool = max(cool - 1 / max(fps, 1), 0);
stamp = above(kick, 0.2) * below(cool, 0.001);
cool = if(stamp, 0.18, cool);
q1 = depth;
q2 = twist;
q6 = dd;
q9 = stamp;

warp:
shader_body {
 vec2 s = texsize.xy / min(texsize.x, texsize.y);
 vec2 src = vec2(uv_orig.x, uv_orig.y + q6 / 2.0);
 float ink = texture(sampler_main, src).x * 0.995 * step(2.5, frame) * step(src.y, 1.0);
 ret = vec3(ink, 0.0, 0.0);
}

comp:
uniform sampler2D sampler_fw_cover;
 shader_body {
  vec2 s = texsize.xy / min(texsize.x, texsize.y);
  vec2 p = (uv - 0.5) * s;
  p += vec2(0.07 * sin(time * 0.23), 0.06 * cos(time * 0.19));
  float r0 = max(length(p), 0.002);
  float a = atan(p.y, p.x);
  float r = r0 * (1.0 + 0.07 * sin(a * 3.0 + q1 * 1.7) * clamp(mid_att, 0.0, 2.0));
  r *= 1.0 + 0.10 * q3 + 0.08 * q5;
  float dep = 0.26 / r;
  float aR = atan(-p.y, -p.x) + 3.14159265;
  float side = smoothstep(0.03, -0.03, p.x);
  vec2 tL = vec2(a / 6.2831853 * 2.0 + q2 + 0.06 * dep, dep + q1);
  vec2 mL = 1.0 - abs(1.0 - mod(tL, 2.0));
  vec2 maL = 1.0 - abs(1.0 - mod(tL + vec2(0.012, 0.0), 2.0));
  vec2 mdL = 1.0 - abs(1.0 - mod(tL + vec2(0.0, 0.02), 2.0));
  vec3 wL = vec3(dot(texture(sampler_fw_cover, vec2(mL.x, 1.0 - mL.y)).xyz, vec3(0.299, 0.587, 0.114)),
                     dot(texture(sampler_fw_cover, vec2(maL.x, 1.0 - maL.y)).xyz, vec3(0.299, 0.587, 0.114)),
                     dot(texture(sampler_fw_cover, vec2(mdL.x, 1.0 - mdL.y)).xyz, vec3(0.299, 0.587, 0.114)));
  vec2 tR = vec2(aR / 6.2831853 * 2.0 + q2 + 0.06 * dep, dep + q1);
  vec2 mR = 1.0 - abs(1.0 - mod(tR, 2.0));
  vec2 maR = 1.0 - abs(1.0 - mod(tR + vec2(0.012, 0.0), 2.0));
  vec2 mdR = 1.0 - abs(1.0 - mod(tR + vec2(0.0, 0.02), 2.0));
  vec3 wR = vec3(dot(texture(sampler_fw_cover, vec2(mR.x, 1.0 - mR.y)).xyz, vec3(0.299, 0.587, 0.114)),
                     dot(texture(sampler_fw_cover, vec2(maR.x, 1.0 - maR.y)).xyz, vec3(0.299, 0.587, 0.114)),
                     dot(texture(sampler_fw_cover, vec2(mdR.x, 1.0 - mdR.y)).xyz, vec3(0.299, 0.587, 0.114)));
  vec3 wall = mix(wL, wR, side);
  float cl = wall.x;
  float ca = wall.y;
  float cd = wall.z;
  vec3 wn = normalize(vec3((cl - ca) * 5.0, (cl - cd) * 5.0, 1.0));
  vec3 wl = normalize(vec3(0.3, -0.7, 0.65));
  float shade = 0.45 + 0.75 * max(dot(wn, wl), 0.0);
  float lum = clamp((cl - 0.5) * 1.6 + 0.5, 0.0, 1.0);
  float col_r_x = clamp(lum, 0.0, 1.0) * 5.0;
  vec3 col_r = mix(NOKKVI_RAMP0, NOKKVI_RAMP1, clamp(col_r_x, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP2, clamp(col_r_x - 1.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP3, clamp(col_r_x - 2.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP4, clamp(col_r_x - 3.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP5, clamp(col_r_x - 4.0, 0.0, 1.0));
  vec3 col = mix(NOKKVI_BG, col_r, smoothstep(0.02, 0.35, lum));
  col = mix(col, NOKKVI_TEXT, smoothstep(0.85, 1.0, lum) * 0.7);
  col *= shade;
  float band = pow(abs(sin((dep + q1) * 4.7123889)), 28.0);
  col += mix(NOKKVI_HIGHLIGHT, NOKKVI_TEXT, q3 * 0.5) * band * (0.2 + 0.7 * q3 + 0.6 * q5);
  col += NOKKVI_WARM * band * clamp(treb_att - 1.0, 0.0, 1.0) * 0.5;
  float fog = smoothstep(0.03, 0.30, r0);
  float fogf = fog * fog;
  col = mix(NOKKVI_BG, col, fogf);
  vec2 hu = vec2(a / 6.2831853 + 0.5, dep / 2.0);
  vec2 huR = vec2(aR / 6.2831853 - 0.5, hu.y);
  float hoop = mix(texture(sampler_fw_main, hu).x, texture(sampler_fw_main, huR).x, side) * step(hu.y, 1.0);
  col += NOKKVI_ACCENT * GetBlur1(hu).x * step(hu.y, 1.0) * 1.5 * fogf;
  col += mix(NOKKVI_HIGHLIGHT, NOKKVI_TEXT, hoop) * hoop * (2.0 + 0.8 * q3) * fogf;
  col += NOKKVI_ACCENT * smoothstep(0.035, 0.0, abs(r0 - 0.07 - 0.05 * q3 - 0.04 * q5)) * (0.3 + 0.7 * q3 + 0.6 * q5);
  col *= 1.0 + 0.4 * q5;
  col *= 0.85 + 0.15 * smoothstep(0.95, 0.3, r0);
  ret = col;
 }
